effect.shader:
void main() {
    vec2 p = acScreenNorm - center;
    float r = length(p);
    float peso = smoothstep(innerRadius, innerRadius + 0.3, r);
    if (peso <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }

    vec2 dir = (r > 1e-5) ? p / r : vec2(0.0);
    int n = clamp(int(samples), 4, 48);

    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        soma += texture(inputImg, acScreenNorm - dir * strength * t * peso);
    }
    fragColor = soma / float(n + 1);
}
